function checkForbiddenWords(elements) {
  let forbiddenWordsArr = [],
    errorsSet = new Set(),
    popupVal = $("#popup-forbidden-words").val();

  if (popupVal) {
    try {
      forbiddenWordsArr = JSON.parse(popupVal).map((w) => w.toLowerCase());
    } catch (e) {
      console.error("Ошибка парсинга запрещённых слов", e);
      return { hasForbidden: false, words: [] };
    }
  }

  const excludedNames = ["tg", "site", "vk", "dzen", "max"];

  function escapeRegExp(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  $(elements).each(function () {
    let $el = $(this),
      val = $el.val() || "",
      name = $el.attr("name") || "";

    // Определяем, является ли поле контентом TinyMCE (textarea)
    let isRichText = $el.is("textarea") || name === "content";

    if (!isRichText) {
      // Для заголовка: ЛЮБОЙ HTML-тег вызывает ошибку
      if (val.match(/<[^>]+>/g)) {
        errorsSet.add("HTML-вставка");
      }
    } else {
      // Для TinyMCE: обычные теги пропускаем, но блокируем вредоносный XSS-код
      let dangerousHtml =
        /<(script|iframe|object|embed|form|meta|link)\b[^>]*>|on\w+\s*=|javascript:/i;
      if (dangerousHtml.test(val)) {
        errorsSet.add("HTML-вставка"); // Выводим общую фразу вместо названия тегов
      }
    }

    // Проверка на ссылки (если поле не входит в белый список исключений)
    if (!excludedNames.includes(name)) {
      let urlRegex = /https?:\/\/[^\s"\'<>]+/g;
      let match;
      while (null !== (match = urlRegex.exec(val))) {
        errorsSet.add(`ссылка – ${match[0]}`);
      }
      val = val.replace(/https?:\/\/[^\s"\'<>]+/g, "");
    }

    // Вырезаем все теги перед проверкой на стоп-слова
    val = val.replace(/<[^>]+>/g, "");

    // Проверка на запрещенные слова
    let lowerVal = val.toLowerCase();
    for (let word of forbiddenWordsArr) {
      if (word) {
        let reg = new RegExp(
          `(^|\\P{L})${escapeRegExp(word)}(?=\\P{L}|$)`,
          "iu"
        );
        if (reg.test(lowerVal)) {
          errorsSet.add(word);
        }
      }
    }
  });

  return { hasForbidden: errorsSet.size > 0, words: Array.from(errorsSet) };
}

// 2. Функция вывода попапа с ошибками
function showForbiddenPopup(wordsArr) {
  const formattedWords = wordsArr.map((w) => `"${w}"`).join(", ");
  $("#forbidden-words-list").text(formattedWords);
  $("#forbidden-popup").fadeIn();
}
function clampLines(e, t) {
  const a = e[0];
  if (!a) return;
  const o = document.createElement("span");
  (o.textContent = "A"),
    (o.style.visibility = "hidden"),
    (o.style.position = "absolute");
  const n = getComputedStyle(a);
  (o.style.fontSize = n.fontSize),
    (o.style.fontFamily = n.fontFamily),
    (o.style.fontWeight = n.fontWeight),
    (o.style.lineHeight = n.lineHeight),
    a.appendChild(o);
  const i = o.offsetHeight;
  if ((a.removeChild(o), !i || i <= 0)) return;
  const c = i * t,
    r = e.data("original") || e.text().trim();
  if (!r) return;
  if ((e.text(r), a.scrollHeight <= c)) return;
  let s,
    p = 0,
    l = r.length;
  for (; p <= l; )
    (s = Math.floor((p + l) / 2)),
      e.text(r.slice(0, s) + "…"),
      a.scrollHeight > c ? (l = s - 1) : (p = s + 1);
  e.text(r.slice(0, l) + "…");
}
