$('.filter').on('click', '.btn-confirm-selection', function () {
  let parent = $(this).closest('.custom-filter-select');
  let parentId = parent.attr('id');
  let checkedValues = [];
  
  parent.find('input:checkbox:checked').each(function () {
      checkedValues.push($(this).val());
  });

  parent.find('.confirmed-values').val(checkedValues.join(','));

  let prefixText = 'Удобства';
  if (parentId === 'filter-equipment') prefixText = 'Оборудование';
  if (parentId === 'filter-price') prefixText = 'Стоимость занятия';

  let defaultText = 'Все удобства';
  if (parentId === 'filter-equipment') defaultText = 'Всё оборудование';
  if (parentId === 'filter-price') defaultText = 'Стоимость занятия';
  
  if (checkedValues.length > 0) {
      parent.find('.custom-select-trigger span').text(`${prefixText} (${checkedValues.length})`);
  } else {
      parent.find('.custom-select-trigger span').text(defaultText);
  }

  parent.removeClass('open');
});

$('.filter').on('click', '.btn-reset-selection', function () {
  let parent = $(this).closest('.custom-filter-select');
  let parentId = parent.attr('id');
  
  parent.find('input:checkbox').prop('checked', false);
  parent.find('.confirmed-values').val('');
  
  let defaultText = 'Все удобства';
  if (parentId === 'filter-equipment') defaultText = 'Всё оборудование';
  if (parentId === 'filter-price') defaultText = 'Стоимость занятия';
  
  parent.find('.custom-select-trigger span').text(defaultText);
});

