    e.preventDefault();
    const $field = $(this).closest(".captcha-field"),
      $code = $field.find('input[name="captcha_code"]'),
      $id = $field.find('input[name="captcha_id"]'),
      $img = $field.find("img"),
      ts = Date.now();

    $img.attr("src", "/libs/securimage/securimage_show.php?id=" + ts);
