  $("#support-message-popup").on("submit", function (e) {
    e.preventDefault();
  
    const $form = $(this);
    const $captchaField = $form.find(".captcha-field");
    const $captchaCode = $captchaField.find('input[name="captcha_code"]');
    const $captchaId = $captchaField.find('input[name="captcha_id"]');
    const $captchaImg = $captchaField.find("img");
    const $captchaError = $captchaField.find(".captcha-error");
  
    $form.find(".invalid-feedback").text("");
    $form.find("input, textarea").removeClass("error");
    $captchaError.hide().text("");
  
    const $submitBtn = $form.find("#btn-support-message-popup");
    $submitBtn.prop("disabled", true).text("Отправка...");
  
    $.ajax({
      type: "POST",
      url: "/actions/mail/note_notification.php",
      dataType: "json",
      data: $form.serialize(),
      success: function (response) {
        if (response.success) {
          $(".support-message").fadeOut(200);
          $(".support-message-end").fadeIn(200);
          $form.trigger("reset");
          $submitBtn.prop("disabled", false).text("Отправить");
          return;
        }
  
        if (response.error) {
          if (typeof response.error === "object") {
            $.each(response.error, function (field, message) {
              if (field === "captcha_error") {
                $captchaCode.addClass("error");
                $captchaError.text(message).show();
                const ts = Date.now();
                $captchaImg.attr("src", "/libs/securimage/securimage_show.php?id=" + ts);
                $captchaId.val(ts);
                $captchaCode.val("").focus();
              } else {
                const $input = $form.find(`[name="${field}"]`);
                $input.addClass("error");
                $input.closest(".field").find(".invalid-feedback").text(message).show();
              }
            });
          } else {
            alert(response.error);
          }
        }
  
        $submitBtn.prop("disabled", false).text("Отправить");
      },
      error: function (xhr) {
        if (xhr.status === 403) {
          $form
            .find('[name="message"]')
            .addClass("error")
            .closest(".field")
            .find(".invalid-feedback")
            .text('Обнаружены запрещённые элементы: "HTML-вставка".')
            .show();
        } else {
          $captchaError.text("Ошибка сети или сервера. Попробуйте ещё раз.").show();
          const ts = Date.now();
          $captchaImg.attr("src", "/libs/securimage/securimage_show.php?id=" + ts);
          $captchaId.val(ts);
          $captchaCode.val("").focus();
        }
        $submitBtn.prop("disabled", false).text("Отправить");
      },
    });
  });
